package routes

import (
	"net/http"

	"github.com/gin-gonic/gin"
	"myapp/health"
	"myapp/middleware"
)

func InitializePatientRoutes(r *gin.Engine, chartRepo health.ChartRepository) {
	api := r.Group("/patients")
	api.Use(middleware.AuthenticateTenant())

	api.GET("/:patientID/export-chart", func(c *gin.Context) {
		patientID := c.Param("patientID")
		clinicID := c.GetString("tenant_id")

		chart, err := chartRepo.ExportChartForClinic(c.Request.Context(), patientID, clinicID)
		if err != nil {
			c.JSON(http.StatusNotFound, gin.H{"error": "Chart not found or unauthorized"})
			return
		}
		c.JSON(http.StatusOK, chart)
	})
}
